"""Freeze new numeric-transfer cases and longer requirement dialogues."""
import hashlib
import json
from pathlib import Path
ROOT=Path(__file__).parent
old=ROOT.parent/'decision-lora-9b/train.jsonl'
NUM=json.loads(old.read_text().splitlines()[0])['messages'][0]['content']
DRAFT='Составь задачу Jira на русском. Верни JSON summary, description, questions. Сохрани все согласованные требования и точные границы. В questions включи только оставшиеся открытые вопросы.'
rows=[]
# Every pair changes the final decision while keeping the earlier context constant.
pairs=[
 ('ceiling','basic','Мест в зале','В старой версии 120 мест.', [('Оставляем максимум 115 мест; 115 допускается.',None,115,None,True),('Окончательно: меньше 115 мест, 115 не допускается.',None,115,None,False)]),
 ('floor','basic','Количество шагов','Обсуждали минимум 200 шагов.', [('Теперь требуется не меньше 205 шагов.',205,None,True,None),('Теперь нужно строго больше 205 шагов.',205,None,False,None)]),
 ('exact','basic','Количество секций','Предложено 101 секция.', [('Согласовали именно 103 секции, ни больше ни меньше.',103,103,True,True),('Все предложения отменены, число секций выберут позже.',None,None,None,None)]),
 ('revoked','basic','Время промывки, секунд','Утвердили ровно 96 секунд.', [('Это решение отменили. Новый срок пока не выбран.',None,None,None,None),('Изменили решение: теперь ровно 98 секунд.',98,98,True,True)]),
 ('other-topic','basic','Количество жетонов в конверте','Для конверта максимум 106 жетонов. Для отдельной коробки утвердили 160.', [('Требование конверта оставляем без изменений. Речь сейчас только о нём.',None,106,None,True),('У конверта теперь строго меньше 104 жетонов. Коробку не меняем.',None,104,None,False)]),
 ('no-invention','basic','Время ожидания, минут','Раньше обсуждали диапазон от 4 до 14 минут.', [('Этот диапазон отменён. Теперь только верхняя граница: максимум 12 минут.',None,12,None,True),('Диапазон отменён. Теперь только нижняя граница: не меньше 6 минут.',6,None,True,None)]),
 ('zero','extended','Количество ошибок','Обсуждали допустимое число ошибок.', [('Допустимо не больше нуля ошибок.',None,0,None,True),('Число ошибок строго больше нуля.',0,None,False,None)]),
 ('negative','extended','Температура, градусов','Для текущего режима раньше предлагали минус 10 градусов.', [('Окончательно: температура не выше минус 12 градусов.',None,-12,None,True),('Окончательно: температура выше минус 12 градусов, сама граница исключена.',-12,None,False,None)]),
 ('decimal','extended','Масса, кг','В заметках фигурировало 3 кг.', [('Теперь масса строго меньше 2,75 кг.',None,2.75,None,False),('Теперь масса не меньше 2,75 кг.',2.75,None,True,None)]),
 ('range','extended','Длина, см','Старый диапазон был от 10 до 20 см.', [('Новый диапазон: от 11 до 19 см, обе границы включены.',11,19,True,True),('Новый диапазон: больше 11 и меньше 19 см, обе границы исключены.',11,19,False,False)]),
 ('mixed-range','extended','Влажность, процентов','Работаем над новым интервалом влажности.', [('Допускается от 36 включительно до 64 не включительно.',36,64,True,False),('Допускается больше 36 и не больше 64.',36,64,False,True)]),
 ('decimal-exact','extended','Объём, литров','Предложили 1,25 литра.', [('Утвердили ровно 1,25 литра.',1.25,1.25,True,True),('1,25 литра осталось предложением; решение после проверки.',None,None,None,None)]),
]
for topic,group,target,earlier,variants in pairs:
 for i,(decision,lo,hi,li,ui) in enumerate(variants):
  expected=dict(status='open' if lo is None and hi is None else 'final',lower=lo,upper=hi,lowerInclusive=li,upperInclusive=ui)
  messages=[dict(role='system',content=NUM),dict(role='user',content=f'Условие: {target}. {earlier}'),dict(role='assistant',content='Какое решение действует сейчас?'),dict(role='user',content=decision+' Выдели действующую числовую норму.'),dict(role='assistant',content=json.dumps(expected,ensure_ascii=False))]
  rows.append(dict(id=f'{topic}-{i}',topic=topic,task='bounds',group=group,messages=messages))

def draft(id,turns,title,description,questions=None):
 assert len(turns)==7
 messages=[dict(role='system',content=DRAFT)]+[dict(role='user' if i%2==0 else 'assistant',content=t) for i,t in enumerate(turns)]
 messages.append(dict(role='assistant',content=json.dumps(dict(summary=title,description=description,questions=questions or []),ensure_ascii=False)))
 rows.append(dict(id=id,topic=id,task='draft',group='long-dialogue',messages=messages))

draft('menu-revert',['Раздел «Счета» переименуем в «Оплата». Ссылку не меняем.','Менять содержимое?','Нет. Ещё кнопки этого раздела должны быть серыми.','Оставляем новое название?','Нет, переименование отменили. Название снова «Счета», серый цвет кнопок остаётся.','А ссылку менять?','Нет. Составь итоговую задачу без отменённого переименования.'],'Цвет кнопок раздела счетов','Сделать кнопки раздела «Счета» серыми. Название, содержимое и ссылку оставить прежними.')
draft('backup-recipients',['Отчёт резервного копирования отправлять администратору. Показывать дату и результат, путь к файлу скрыть.','Добавить руководителя?','Нет. Для другого отчёта руководитель нужен, но это другая задача.','Результат резервного копирования оставляем?','Да, а дату заменяем временем завершения.','Получатель тот же?','Да. Оформи только отчёт резервного копирования.'],'Отчёт резервного копирования','Отправлять администратору время завершения и результат резервного копирования. Путь к файлу скрывать. Руководителю этот отчёт не отправлять.')
draft('drawing-unresolved',['В экспорт чертежа включаем масштаб и номер версии. Формат пока не выбрали: обсуждали SVG.','Запишем SVG как временный формат?','Нет, даже временно не утверждали.','Может, убрать масштаб?','Масштаб согласован, его оставляем.','Что спрашивать в задаче?','Только формат экспорта. Составь задачу.'],'Экспорт чертежа','В экспорт чертежа включать масштаб и номер версии. Формат пока не выбран; SVG только обсуждался.',['Какой формат экспорта чертежа выбрать?'])
draft('refresh-correction',['Панель обновляется раз в 22 секунды. Показывать число активных заявок.','Показывать имена заявителей?','Нет, имена скрыты.','22 секунды окончательно?','Исправляем интервал на 18 секунд, ровно 18.','Остальные условия меняются?','Нет. Подготовь задачу по последнему решению.'],'Обновление панели заявок','Обновлять панель каждые 18 секунд. Показывать число активных заявок. Имена заявителей скрывать.')
draft('explicit-trigger',['Уведомление дежурному отправлять только после неудачной проверки. В нём код проверки.','При успешной проверке тоже отправлять?','Нет.','Добавить текст ошибки?','Да, но имя пользователя в уведомлении не показывать.','Меняем получателя?','Нет, составь задачу со всеми согласованными условиями.'],'Уведомление о неудачной проверке','Только после неудачной проверки отправлять дежурному код проверки и текст ошибки. Имя пользователя не показывать. После успешной проверки уведомление не отправлять.')
draft('print-columns',['Печатать накладную: номер, дата, количество. Телефон покупателя не печатать.','Нужен поиск по номеру?','Нет, речь только о печати.','Какой формат даты?','ДД.ММ.ГГГГ.','Количество убрать?','Нет, оставляем. Составь задачу именно о печати.'],'Печать накладной','Печатать номер накладной, дату в формате ДД.ММ.ГГГГ и количество. Телефон покупателя не печатать. Поиск не добавлять.')
draft('sensor-topic',['Показание датчика: температура строго ниже 72 градусов. Показывать номер датчика технику.','А режим вентилятора?','Для вентилятора утвердили 3 скорости, но это другая задача.','В текущую задачу добавить вентилятор?','Нет. У датчика ещё скрываем серийный номер владельца.','72 градуса подходят?','Нет. Составь только задачу датчика.'],'Проверка показания датчика','Температура должна быть строго ниже 72 градусов; 72 не допускается. Технику показывать номер датчика. Серийный номер владельца скрывать. Вентилятор вне задачи.')
draft('single-open-field',['Карточка заказа показывает статус и дату создания.','Добавить сумму?','Нет. Цвет статуса ещё не выбран.','Дату можно убрать?','Нет, дата обязательна.','Статус показываем текстом или значком?','Текстом, это утвердили. Составь задачу, вопрос оставь только о цвете.'],'Карточка заказа','Показывать статус текстом и дату создания. Сумму не добавлять. Цвет статуса ещё не выбран.',['Какой цвет использовать для статуса?'])
assert len(rows)==32 and len({r['id'] for r in rows})==32
(ROOT/'test.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
# Ensure these exact prompts were never used in the training data of the candidate.
train=[json.loads(s) for s in (ROOT.parent/'requirements-draft-v5/train.jsonl').read_text().splitlines()]
inputs={json.dumps(r['messages'][:-1],ensure_ascii=False) for r in train}
assert all(json.dumps(r['messages'][:-1],ensure_ascii=False) not in inputs for r in rows)
print('Frozen 24 paired numeric probes and 8 seven-turn draft dialogues.')
